def calculate_energy(s):
    product_odd = 1
    sum_even = 0
    has_non_zero_odd = False 
    for i, char in enumerate(s):
        digit = int(char)
        position = i + 1  
        if position % 2 == 1: 
            if digit != 0:
                product_odd *= digit
                has_non_zero_odd = True
        else: 
            sum_even += digit
    if not has_non_zero_odd:
        product_odd = 0
    return product_odd, sum_even
def main():
    t = int(input())
    for _ in range(t):
        s = input().strip()
        product_odd, sum_even = calculate_energy(s)
        print(f"{product_odd} {sum_even}")
if __name__ == "__main__":
    main()

